R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_rkfix2/prompts $R/sb_rkfix2/out
echo  | base64 -d > $R/sb_rkfix2/prompts/sb_rkfix2.md
{ echo sb_rkfix2; cat $R/sb_queue/queue.txt; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; cat $R/sb_queue/queue.txt | tr "\n" " "; echo
mkdir -p $R/sb_f64fix; cp $R/sb_cursor_probe/AGENTS.md $R/sb_f64fix/AGENTS.md
echo  | base64 -d > $R/sb_f64fix/PROMPT.md
cd $R/sb_f64fix && tmux new-session -d -s sb_f64fix "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "
